/**
 * Typed error enum mapped directly to Swift `throws TTZipError`.
 */
sealed class TtZipException: kotlin.Exception() {
    
    class FileNotFound(
        
        val `path`: kotlin.String
        ) : TtZipException() {
        override val message
            get() = "path=${ `path` }"
    }
    
    class InvalidPassword(
        ) : TtZipException() {
        override val message
            get() = ""
    }
    
    class CorruptHeader(
        
        val `details`: kotlin.String, 
        
        val `offset`: kotlin.ULong
        ) : TtZipException() {
        override val message
            get() = "details=${ `details` }, offset=${ `offset` }"
    }
    
    class SecurityViolation(
        
        val `reason`: kotlin.String
        ) : TtZipException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class EngineException(
        
        val `code`: kotlin.Int
        ) : TtZipException() {
        override val message
            get() = "code=${ `code` }"
    }
    
    class IoException(
        
        val `message`: kotlin.String
        ) : TtZipException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class Cancelled(
        ) : TtZipException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TtZipException> {
        override fun lift(error_buf: RustBuffer.ByValue): TtZipException = FfiConverterTypeTTZipError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTTZipError : FfiConverterRustBuffer<TtZipException> {
    override fun read(buf: ByteBuffer): TtZipException {
        

        return when(buf.getInt()) {
            1 -> TtZipException.FileNotFound(
                FfiConverterString.read(buf),
                )
            2 -> TtZipException.InvalidPassword()
            3 -> TtZipException.CorruptHeader(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                )
            4 -> TtZipException.SecurityViolation(
                FfiConverterString.read(buf),
                )
            5 -> TtZipException.EngineException(
                FfiConverterInt.read(buf),
                )
            6 -> TtZipException.IoException(
                FfiConverterString.read(buf),
                )
            7 -> TtZipException.Cancelled()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TtZipException): ULong {
        return when(value) {
            is TtZipException.FileNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`path`)
            )
            is TtZipException.InvalidPassword -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is TtZipException.CorruptHeader -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
                + FfiConverterULong.allocationSize(value.`offset`)
            )
            is TtZipException.SecurityViolation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is TtZipException.EngineException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterInt.allocationSize(value.`code`)
            )
            is TtZipException.IoException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is TtZipException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: TtZipException, buf: ByteBuffer) {
        when(value) {
            is TtZipException.FileNotFound -> {
                buf.putInt(1)
                FfiConverterString.write(value.`path`, buf)
                Unit
            }
            is TtZipException.InvalidPassword -> {
                buf.putInt(2)
                Unit
            }
            is TtZipException.CorruptHeader -> {
                buf.putInt(3)
                FfiConverterString.write(value.`details`, buf)
                FfiConverterULong.write(value.`offset`, buf)
                Unit
            }
            is TtZipException.SecurityViolation -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is TtZipException.EngineException -> {
                buf.putInt(5)
                FfiConverterInt.write(value.`code`, buf)
                Unit
            }
            is TtZipException.IoException -> {
                buf.putInt(6)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is TtZipException.Cancelled -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Callback interface protocol implemented in Swift.
 */
public interface ProgressHandler {
    
    fun `onProgress`(`processedBytes`: kotlin.ULong, `totalBytes`: kotlin.ULong, `currentEntry`: kotlin.String?): kotlin.Boolean
    
    companion object
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}

// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceProgressHandler {
    internal object `onProgress`: UniffiCallbackInterfaceProgressHandlerMethod0 {
        override fun callback(`uniffiHandle`: Long,`processedBytes`: Long,`totalBytes`: Long,`currentEntry`: RustBuffer.ByValue,`uniffiOutReturn`: ByteByReference,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeProgressHandler.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onProgress`(
                    FfiConverterULong.lift(`processedBytes`),
                    FfiConverterULong.lift(`totalBytes`),
                    FfiConverterOptionalString.lift(`currentEntry`),
                )
            }
            val writeReturn = { value: kotlin.Boolean -> uniffiOutReturn.setValue(FfiConverterBoolean.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeProgressHandler.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceProgressHandler.UniffiByValue(
        `onProgress`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_ttzip_engine_fn_init_callback_vtable_progresshandler(vtable)
    }
}

